document.addEventListener('DOMContentLoaded',()=>{window.lucide?.createIcons();const page=document.body.dataset.page;document.querySelectorAll('.au-header [data-review-page]').forEach(a=>{if(a.dataset.reviewPage===page)a.setAttribute('aria-current','page')});document.querySelector('.au-letter-form')?.addEventListener('submit',event=>{event.preventDefault();const status=event.currentTarget.querySelector('.au-form-status');status.hidden=false;status.textContent='Это макет: сообщение не отправлено.';});});